# owner: platform
"""Contact sheet for substitute teachers."""

from typing import List

from rosterkit.models import Student


def _check(students):
    if not students:
        raise ValueError("no students given")
    for stud in students:
        if not stud.email:
            name = stud.display_name
            raise ValueError(f"no email for {name}")


def _cells(stud):
    return (stud.display_name, stud.section, stud.email)


def _pad(cells, widths):
    pairs = zip(cells, widths)
    return "  ".join(c.ljust(w) for c, w in pairs).rstrip()


# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    _check(students)
    ordered = sorted(students, key=lambda s: s.display_name)
    table = [_cells(stud) for stud in ordered]
    widths = [max(map(len, col)) for col in zip(*table)]
    return [_pad(cells, widths) for cells in table]
