cat > tests/test_contacts.py <<'EOF'
# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def _stud(last, section, email="a@x.org"):
    return Student("id", last, "Kim", section, email)


class ContactRowTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            _stud("Zed", "B2", "z@x.org"),
            _stud("Adams", "A1", "a@x.org")
        ])
        self.assertEqual(rows, [
            "Adams, Kim  A1  a@x.org",
            "Zed, Kim    B2  z@x.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaises(ValueError) as ctx:
            contact_rows([_stud("Adams", "A1", None)])
        self.assertIn("Adams, Kim", str(ctx.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
